// NEWCOMER PRICING — `CrapsBattle._entryPrice`. Every PAID craps burn (a window or custom seat, a
// whole day, a future-day purchase, a paid window upgrade) costs `price + price / 20` for a wallet
// with no more than two credited mint levels, no mint at or after the previous level, and no deity
// pass. Comp-paid entries never pay it, and the premium never reaches the seat's bankroll, bounty
// or rewards — it is burn only.
const CRAPS_MINT_LEVEL_COUNT_SHIFT = 24n; // BitPackingLib.LEVEL_COUNT_SHIFT
const CRAPS_MINT_DEITY_SHIFT = 172n; // BitPackingLib.HAS_DEITY_PASS_SHIFT
const CRAPS_UINT24_MASK = 0xFFFFFFn;
const CRAPS_NEWCOMER_PREMIUM_DIVISOR = 20n;
const CRAPS_GAME_PRICING_ABI = Object.freeze([
  'function mintPackedFor(address player) view returns (uint256)',
  'function level() view returns (uint24)',
]);

/** Whether `_entryPrice` charges this mint history the newcomer premium at `gameLevel`. */
export function crapsNewcomerPricing(mintPacked, gameLevel) {
  const packed = asUint(mintPacked, 'Mint history');
  const level = asUint(gameLevel, 'Game level');
  if (((packed >> CRAPS_MINT_LEVEL_COUNT_SHIFT) & CRAPS_UINT24_MASK) > 2n
    || ((packed >> CRAPS_MINT_DEITY_SHIFT) & 1n) !== 0n) return false;
  const lastMintLevel = packed & CRAPS_UINT24_MASK;
  return !(lastMintLevel !== 0n && lastMintLevel + 1n >= level);
}

/** A paid entry's burn in wei: `_entryPrice(player, base)`. */
export function crapsEntryPriceWei(baseWei, newcomer = false) {
  const base = asUint(baseWei, 'Craps entry price');
  return newcomer ? base + base / CRAPS_NEWCOMER_PREMIUM_DIVISOR : base;
}

/** The same burn for a whole-FLIP quote. Every paid craps price is a multiple of 100 FLIP. */
export function crapsEntryPriceFlip(baseFlip, newcomer = false) {
  return crapsEntryPriceWei(asUint(baseFlip, 'Craps entry price') * CRAPS_FLIP_WEI, newcomer) / CRAPS_FLIP_WEI;
}

/**
 * Whether `player`'s next PAID craps burn carries the newcomer premium. Reads GAME's raw mint
 * history and level exactly as `_entryPrice` does; `null` when no read is possible.
 */
export async function readCrapsNewcomerPricing(player) {
  if (!ethers.isAddress(String(player ?? ''))) return false;
  const provider = readerProvider();
  const game = CONTRACTS.GAME;
  if (!provider || !ethers.isAddress(String(game ?? ''))) return null;
  const reader = new ethers.Contract(game, CRAPS_GAME_PRICING_ABI, provider);
  const [packed, level] = await Promise.all([reader.mintPackedFor(player), reader.level()]);
  return crapsNewcomerPricing(packed, level);
}
